//! N7: checked named-coordinate dictionary and sparse action fixture.
//!
//! The checked JSON is generated by
//! `fock_sirk/examples/sm_named_dictionary.rs`. This test re-derives every
//! component from the native builder and from the independent Cadabra import,
//! replays the action cells, and keeps the negative controls hard failures.

use fock_sirk::joint_sirk::joint_norm;
use nested_fock_algebra::exact_inner::{
    ActionError, ActionLimits, InnerExpr as E, JointInnerBasis as B, JointOuterBasis as O,
    NestedVector,
};
use nested_fock_algebra::sm_full::*;
use num_complex::Complex64 as C;
use serde_json::{Value, json};
use sha2::{Digest, Sha256};
use std::collections::{BTreeMap, BTreeSet};

const FIXTURE: &str = include_str!("../../docs/fixtures/sm_named_dictionary.json");
const LATEX: &str = include_str!("../../docs/fixtures/sm_full_cadabra.latex");

fn fixture() -> Value {
    serde_json::from_str(FIXTURE).expect("checked fixture is valid JSON")
}

fn c(v: &Value) -> C {
    C::new(v[0].as_f64().unwrap(), v[1].as_f64().unwrap())
}

fn matrix(v: &Value) -> [[C; 3]; 3] {
    std::array::from_fn(|i| std::array::from_fn(|j| c(&v[i][j])))
}

fn parameters_from(f: &Value) -> SmParameters {
    let p = &f["parameters"];
    SmParameters {
        gs: p["gs"].as_f64().unwrap(),
        gw: p["gw"].as_f64().unwrap(),
        gy: p["gy"].as_f64().unwrap(),
        lambda: p["lambda"].as_f64().unwrap(),
        vev: p["vev"].as_f64().unwrap(),
        yu: matrix(&p["yu"]),
        yd: matrix(&p["yd"]),
        ynu: matrix(&p["ynu"]),
        ye: matrix(&p["ye"]),
    }
}

fn coordinate_name(m: u32) -> String {
    for i in 0..3 {
        if m == coord::x(i) {
            return format!("x_{i}");
        }
    }
    for a in 0..8 {
        for i in 0..3 {
            if m == coord::g(a, i) {
                return format!("g_{a}_{i}");
            }
            for j in 0..3 {
                if m == coord::dg(a, i, j) {
                    return format!("dg_{a}_{i}_{j}");
                }
            }
        }
    }
    for a in 0..3 {
        for i in 0..3 {
            if m == coord::w(a, i) {
                return format!("w_{a}_{i}");
            }
            for j in 0..3 {
                if m == coord::dw(a, i, j) {
                    return format!("dw_{a}_{i}_{j}");
                }
            }
        }
    }
    for i in 0..3 {
        if m == coord::b(i) {
            return format!("b_{i}");
        }
        for j in 0..3 {
            if m == coord::db(i, j) {
                return format!("db_{i}_{j}");
            }
        }
    }
    for a in 0..4 {
        if m == coord::phi(a) {
            return format!("phi_{a}");
        }
        for i in 0..3 {
            if m == coord::dphi(a, i) {
                return format!("dphi_{a}_{i}");
            }
        }
    }
    panic!("unnamed coordinate {m}");
}

fn close(a: C, b: C) {
    assert!((a - b).norm() < 1e-10, "{a} != {b}");
}

fn state_digest(state: &NestedVector) -> String {
    let mut hash = Sha256::new();
    for (basis, amplitude) in state {
        hash.update(
            format!(
                "{basis:?}|{}+{}i\n",
                amplitude.re.to_bits(),
                amplitude.im.to_bits()
            )
            .as_bytes(),
        );
    }
    format!("{:x}", hash.finalize())
}

fn model_parameters(value: &Value) -> SmParameters {
    parameters_from(value)
}

fn assert_coordinates(f: &Value) {
    assert_eq!(f["coordinates"]["count"].as_u64(), Some(163));
    assert_eq!(f["coordinates"]["active_count"].as_u64(), Some(40));
    let names = f["coordinates"]["names"].as_array().unwrap();
    assert_eq!(names.len(), 163);
    for (m, entry) in names.iter().enumerate() {
        assert_eq!(
            entry[0].as_str().unwrap(),
            coordinate_name(m as u32).as_str()
        );
        assert_eq!(entry[1].as_u64(), Some(m as u64));
    }
    let active: Vec<u64> = f["coordinates"]["active"]
        .as_array()
        .unwrap()
        .iter()
        .map(|v| v.as_u64().unwrap())
        .collect();
    assert_eq!(
        active,
        coord::active()
            .iter()
            .map(|&m| m as u64)
            .collect::<Vec<_>>()
    );
}

fn assert_higgs(f: &Value) -> Result<(), String> {
    let slots = f["higgs_slots"].as_array().ok_or("higgs slots")?;
    if slots.len() != 4 {
        return Err("not all four real Higgs slots are bound".into());
    }
    for (a, slot) in slots.iter().enumerate() {
        if slot["name"].as_str() != Some(coordinate_name(coord::phi(a as u32)).as_str()) {
            return Err(format!("moved/renamed Higgs slot {a}"));
        }
        if slot["coordinate"].as_u64() != Some(coord::phi(a as u32) as u64) {
            return Err(format!("moved Higgs coordinate {a}"));
        }
        for up_type in [false, true] {
            let recorded = if up_type {
                slot["up_type_components"].as_array().unwrap()
            } else {
                slot["down_type_components"].as_array().unwrap()
            };
            for entry in recorded {
                let weak = entry[0].as_u64().unwrap() as usize;
                let component = entry[1].as_u64().unwrap() as usize;
                close(
                    C::new(entry[2].as_f64().unwrap(), entry[3].as_f64().unwrap()),
                    higgs_yukawa_component(up_type, weak, component),
                );
            }
        }
    }
    let wall = f["forms"]
        .as_array()
        .ok_or("forms")?
        .iter()
        .find(|form| form["name"] == "wall")
        .ok_or("wall form")?;
    if wall["weight"].as_f64() != Some(0.1 / 4.0) {
        return Err("mutated wall weight".into());
    }
    let phi_squares = (0..4)
        .map(|a| format!("\"q\",{}", coord::phi(a)))
        .collect::<BTreeSet<_>>();
    let terms: BTreeSet<String> = wall["terms"]
        .as_array()
        .unwrap()
        .iter()
        .filter(|term| term[0].as_array().unwrap().len() == 2)
        .map(|term| format!("\"{}\",{}", term[0][0][0].as_str().unwrap(), term[0][0][1]))
        .collect();
    assert_eq!(terms, phi_squares);
    let constant = wall["terms"]
        .as_array()
        .ok_or("wall terms")?
        .iter()
        .find(|term| term[0].as_array().is_some_and(|word| word.is_empty()))
        .ok_or("retained -v^2 constant")?;
    if (constant[1][0].as_f64().unwrap_or(f64::NAN) + 0.49).abs() > 1e-12 {
        return Err("mutated retained Higgs constant".into());
    }
    Ok(())
}

fn assert_kinetic_and_gauge(f: &Value) {
    let blocks = f["kinetic_blocks"].as_array().unwrap();
    assert_eq!(blocks.len(), 3);
    for (axis, block) in blocks.iter().enumerate() {
        assert_eq!(block["axis"].as_u64(), Some(axis as u64));
        for (side, sign) in [("left", -1.0), ("right", 1.0)] {
            for r in 0..2 {
                for s in 0..2 {
                    close(
                        c(&block[side][r][s]),
                        book_kinetic_spin(axis as u32)[r][s] * sign,
                    );
                }
            }
        }
    }
    for (a, recorded) in f["gauge"]["su3_generators"]
        .as_array()
        .unwrap()
        .iter()
        .enumerate()
    {
        for r in 0..3 {
            for s in 0..3 {
                close(c(&recorded[r][s]), su3_generators()[a][r][s]);
            }
        }
    }
    for a in 0..8 {
        for b in 0..8 {
            for k in 0..8 {
                assert!(
                    (f["gauge"]["su3_structure"][a][b][k].as_f64().unwrap()
                        - su3_structure()[a][b][k])
                        .abs()
                        < 1e-12
                );
            }
        }
    }
    for a in 0..3 {
        for b in 0..3 {
            for k in 0..3 {
                assert_eq!(
                    f["gauge"]["weak_epsilon"][a][b][k].as_f64().unwrap(),
                    epsilon(a as u32, b as u32, k as u32)
                );
            }
        }
    }
    for entry in f["gauge"]["hypercharge"].as_array().unwrap() {
        let (species, chirality) = match entry[0].as_str().unwrap() {
            "up_left" => (Species::Up, Chirality::Left),
            "down_left" => (Species::Down, Chirality::Left),
            "neutrino_left" => (Species::Neutrino, Chirality::Left),
            "electron_left" => (Species::Electron, Chirality::Left),
            "up_right" => (Species::Up, Chirality::Right),
            "down_right" => (Species::Down, Chirality::Right),
            "neutrino_right" => (Species::Neutrino, Chirality::Right),
            "electron_right" => (Species::Electron, Chirality::Right),
            other => panic!("unknown hypercharge row {other}"),
        };
        assert_eq!(entry[1].as_f64().unwrap(), species.hypercharge(chirality));
    }
}

fn assert_forms(f: &Value) -> Result<(), String> {
    let model = SmHamiltonian::new(model_parameters(f)).map_err(|e| e.to_string())?;
    let recorded = f["forms"].as_array().ok_or("forms missing")?;
    if recorded.len() != model.forms.len() {
        return Err(format!(
            "form count {} != {}",
            recorded.len(),
            model.forms.len()
        ));
    }
    for form in recorded {
        let name = form["name"].as_str().ok_or("form name")?;
        let native = model
            .forms
            .iter()
            .find(|candidate| candidate.name == name)
            .ok_or_else(|| format!("omitted/moved form {name}"))?;
        if form["weight"].as_f64() != Some(native.weight) {
            return Err(format!("mutated weight for {name}"));
        }
        let terms: Vec<(Vec<(&str, u32)>, C)> = form["terms"]
            .as_array()
            .ok_or("terms")?
            .iter()
            .map(|term| {
                let word = term[0]
                    .as_array()
                    .unwrap()
                    .iter()
                    .map(|v| (v[0].as_str().unwrap(), v[1].as_u64().unwrap() as u32))
                    .collect();
                (word, c(&term[1]))
            })
            .collect();
        if terms.len() != native.polynomial.terms.len() {
            return Err(format!("term count changed for {name}"));
        }
        for (word, coefficient) in &terms {
            let key: Vec<Variable> = word
                .iter()
                .map(|(kind, m)| match *kind {
                    "q" => Variable::Q(*m),
                    "p" => Variable::P(*m),
                    _ => panic!("bad variable kind"),
                })
                .collect();
            let expected = native
                .polynomial
                .terms
                .get(&key)
                .copied()
                .ok_or_else(|| format!("omitted term {name} {word:?}"))?;
            close(*coefficient, expected);
        }
    }
    Ok(())
}

fn assert_matter(f: &Value) -> Result<(), String> {
    let model = SmHamiltonian::new(model_parameters(f)).map_err(|e| e.to_string())?;
    let names: BTreeMap<String, u32> = f["coordinates"]["names"]
        .as_array()
        .unwrap()
        .iter()
        .map(|entry| {
            (
                entry[0].as_str().unwrap().to_string(),
                entry[1].as_u64().unwrap() as u32,
            )
        })
        .collect();
    let mut recorded: BTreeMap<Variable, MatterMatrix> = BTreeMap::new();
    let entries = f["matter"]["entries"].as_array().ok_or("matter entries")?;
    if entries.len() != f["matter"]["entry_count"].as_u64().unwrap() as usize {
        return Err("matter entry_count mismatch".into());
    }
    for entry in entries {
        let variable = entry[0].as_str().ok_or("matter variable")?;
        let (kind, name) = variable.split_once(':').ok_or("matter variable name")?;
        let m = *names
            .get(name)
            .ok_or_else(|| format!("moved coordinate {name}"))?;
        let key = match kind {
            "q" => Variable::Q(m),
            "p" => Variable::P(m),
            _ => return Err("bad matter variable kind".into()),
        };
        *recorded
            .entry(key)
            .or_default()
            .entry((
                entry[1].as_u64().unwrap() as u32,
                entry[2].as_u64().unwrap() as u32,
            ))
            .or_default() += C::new(entry[3].as_f64().unwrap(), entry[4].as_f64().unwrap());
    }
    if recorded.len() != model.matter.len() {
        return Err("matter variable count mismatch".into());
    }
    for (variable, matrix) in &recorded {
        let native = model
            .matter
            .get(variable)
            .ok_or_else(|| format!("omitted matter block {variable:?}"))?;
        if matrix.len() != native.len() {
            return Err(format!("matter entry count changed for {variable:?}"));
        }
        for (pair, coefficient) in matrix {
            let expected = native
                .get(pair)
                .copied()
                .ok_or_else(|| format!("omitted matter entry {variable:?} {pair:?}"))?;
            close(*coefficient, expected);
        }
    }
    if model.matter_entry_polynomials().len() != 1152 {
        return Err("unique matter entry count is not 1152".into());
    }
    Ok(())
}

fn state_from(spec: &Value) -> NestedVector {
    let amplitude = c(&spec["amplitude"]);
    let universes: Vec<(B, u32)> = spec["universes"]
        .as_array()
        .unwrap()
        .iter()
        .map(|universe| {
            let bosons: Vec<(u32, u32)> = universe["bosons"]
                .as_array()
                .unwrap()
                .iter()
                .map(|p| (p[0].as_u64().unwrap() as u32, p[1].as_u64().unwrap() as u32))
                .collect();
            let fermions: Vec<u32> = universe["fermions"]
                .as_array()
                .unwrap()
                .iter()
                .map(|m| m.as_u64().unwrap() as u32)
                .collect();
            (
                B::new(bosons, fermions).unwrap(),
                universe["multiplicity"].as_u64().unwrap() as u32,
            )
        })
        .collect();
    NestedVector::from([(O::graded(universes).unwrap(), amplitude)])
}

fn assert_actions(f: &Value) {
    let native = SmHamiltonian::new(model_parameters(f)).unwrap();
    let fingerprint = |bytes: String| format!("{:x}", Sha256::digest(bytes.as_bytes()));
    assert_eq!(
        fingerprint(format!("{:?}", native.parameters)),
        f["model_sha256"]["parameters"].as_str().unwrap(),
        "parameter instance drifted"
    );
    assert_eq!(
        fingerprint(format!("{:?}", native.forms)),
        f["model_sha256"]["forms"].as_str().unwrap(),
        "form model drifted"
    );
    assert_eq!(
        fingerprint(format!("{:?}", native.matter)),
        f["model_sha256"]["matter"].as_str().unwrap(),
        "matter model drifted"
    );
    let imported = cadabra_import::from_cadabra_latex(model_parameters(f), LATEX).unwrap();
    let limits = ActionLimits {
        max_components: 200_000,
        max_work: 200_000_000,
    };
    let mut sectors = BTreeSet::new();
    for cell in f["action_fixtures"].as_array().unwrap() {
        let state = state_from(&cell["state"]);
        assert_eq!(
            state_digest(&state),
            cell["state_sha256"].as_str().unwrap(),
            "state reconstruction drifted for {}",
            cell["label"]
        );
        let a = native.expression().d_gamma(&state, limits).unwrap();
        let b = imported.expression().d_gamma(&state, limits).unwrap();
        assert_eq!(
            a.len(),
            cell["support"].as_u64().unwrap() as usize,
            "support drifted for {}",
            cell["label"]
        );
        // The independent import may drop exact-zero entries; the action norm
        // and the native digest are the binding checks.
        assert!((joint_norm(&a) - cell["norm"].as_f64().unwrap()).abs() < 1e-9);
        assert!((joint_norm(&b) - joint_norm(&a)).abs() < 1e-8);
        assert_eq!(
            state_digest(&a),
            cell["action_sha256"].as_str().unwrap(),
            "native action drifted for {}",
            cell["label"]
        );
        sectors.insert(cell["sector"].as_str().unwrap().to_string());
    }
    let joined = sectors.iter().cloned().collect::<Vec<_>>().join(" | ");
    for required in [
        "matter=0",
        "matter=1",
        "matter=2",
        "color=2",
        "generation=1",
        "generation=2",
        "chirality=right",
        "outer=two_universes_graded",
    ] {
        assert!(joined.contains(required), "missing sector {required}");
    }
}

#[test]
fn checked_fixture_matches_native_and_independent_cadabra_dictionary() {
    let f = fixture();
    assert_eq!(f["schema"], "sm-named-dictionary/v1");
    assert_coordinates(&f);
    assert_higgs(&f).unwrap();
    assert_kinetic_and_gauge(&f);
    assert_forms(&f).unwrap();
    assert_matter(&f).unwrap();
    assert_eq!(f["forms"].as_array().unwrap().len(), 49);
    assert_eq!(f["matter"]["variable_count"].as_u64(), Some(43));
    assert_eq!(f["matter"]["entry_count"].as_u64(), Some(3366));
    assert_eq!(f["matter"]["unique_matrix_entries"].as_u64(), Some(1152));
}

#[test]
fn sparse_action_cells_cover_sectors_and_spectator_signs() {
    assert_actions(&fixture());
}

#[test]
fn negative_controls_are_hard_failures() {
    let f = fixture();
    // A mutated coefficient/weight changes the dictionary.
    let mut mutated = f.clone();
    mutated["forms"][0]["weight"] = json!(0.6);
    assert!(assert_forms(&mutated).is_err());
    // An omitted form is visible.
    let mut omitted = f.clone();
    omitted["forms"].as_array_mut().unwrap().pop();
    assert!(assert_forms(&omitted).is_err());
    // Moving a named Higgs slot invalidates the dictionary.
    let mut moved = f.clone();
    moved["higgs_slots"][0]["coordinate"] = json!(coord::phi(1));
    let slots = moved["higgs_slots"].as_array_mut().unwrap();
    let name = slots[0]["name"].as_str().unwrap().to_string();
    slots[0]["name"] = json!(coordinate_name(coord::phi(1)));
    slots[1]["name"] = json!(name);
    assert!(assert_higgs(&moved).is_err());
    // An omitted matter entry is visible.
    let mut missing_matter = f.clone();
    missing_matter["matter"]["entries"]
        .as_array_mut()
        .unwrap()
        .pop();
    assert!(assert_matter(&missing_matter).is_err());
    // Resource refusal aborts; it never prunes the action.
    assert!(matches!(
        SmHamiltonian::new(model_parameters(&f))
            .unwrap()
            .expression()
            .d_gamma(
                &state_from(&f["action_fixtures"][0]["state"]),
                ActionLimits {
                    max_components: 200_000,
                    max_work: 1,
                }
            ),
        Err(ActionError::WorkLimit { .. } | ActionError::ComponentLimit { .. })
    ));
    // Noncommuting coefficient imports stay rejected.
    assert!(cadabra_import::polynomial_from_latex("q_{3} * p_{3}", &BTreeMap::new()).is_err());
}

#[test]
fn inner_identity_lifts_to_outer_number_and_products_differ() {
    let limits = ActionLimits::default();
    let one = NestedVector::from([(O::graded([(B::vacuum(), 1)]).unwrap(), C::new(2.0, 0.0))]);
    let scaled = E::Scalar(C::new(3.0, 0.0)).d_gamma(&one, limits).unwrap();
    for (basis, amplitude) in &scaled {
        close(*amplitude, one[basis] * 3.0);
    }
    let two = NestedVector::from([(O::bosonic([(B::vacuum(), 2)]).unwrap(), C::new(1.0, 0.0))]);
    let scaled = E::Scalar(C::new(3.0, 0.0)).d_gamma(&two, limits).unwrap();
    assert!((joint_norm(&scaled) - 6.0).abs() < 1e-10);
    // dGamma(BC) differs from dGamma(B)dGamma(C) on a two-particle sector.
    let q = E::coordinate(coord::phi(0));
    let product = E::Product(vec![q.clone(), q.clone()])
        .d_gamma(&two, limits)
        .unwrap();
    let twice = q
        .d_gamma(&q.d_gamma(&two, limits).unwrap(), limits)
        .unwrap();
    let mut difference = product;
    for (basis, amplitude) in twice {
        *difference.entry(basis).or_default() -= amplitude;
    }
    let difference = difference
        .values()
        .map(|amplitude| amplitude.norm())
        .fold(0.0, f64::max);
    assert!(
        difference > 1.0,
        "dGamma(BC)=dGamma(B)dGamma(C) control failed"
    );
}
